INSERT INTO purpose VALUES('theory-reductions','error::Budget','struct','Names the most redundant cells a check visits before it refuses the walk, so a caller bounds the walk past the cells it gives.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','error::Count','struct','Names a number of cells or of faults, so a fault count and the cells a walk visits are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','error::MorseError','enum','Names why a check, a matching or a reduct gives no answer: the complex''s own fault, a walk past its budget, or a sum past the integers.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','reduction::Answer','type_alias','Names what a step of a reduction gives, its value or a refusal at one of its cells, so each step of a reduction reads alike.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','reduction::Reduction','trait','States a reduction of one complex onto another: the collapse, the inclusion, the witness of each inverse law and the replay, so a Morse collapse and the composite of two are read and checked alike.','collapse oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','reduction::Then','struct','Holds two reductions in sequence: the collapses compose, the inclusions compose in reverse order, and the witnesses whisker, so successive Morse collapses give one reduction.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','refusal::Closure','enum','Names whether a witness runs from one composite to the other, so a forged witness is refused.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','refusal::Refusal','enum','Names why a scheme gives no equivalence or a reduction does not replay: a fault of the matching, a removal the matching lacks or a seam that differs, a forged witness, a circular definition, an image that holds a removed cell, or a critical cell the round trip moves.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','refusal::matched','function','Checks that two lists of cells are equal, and names the cell of the first place where they differ, so a replay refuses a seam that differs.','oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','sum::PartIndex','struct','Names the place of a part in a sum, so a cell, a composite and a witness name the part they belong to.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','sum::Sum','struct','Holds reductions of one type side by side as one reduction, so a family of families reduces part by part and then composes with a reduction of the parts'' targets.','collapse oracle','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','sum::SumFault','enum','Names why a sum cannot answer: no part at a place, two witnesses of two parts, or a part''s own fault with its part.','collapse','fits','sound',NULL);
INSERT INTO purpose VALUES('theory-reductions','sum::Summand','struct','Holds a value of one part of a sum with its part, so the values of two parts stay apart where they agree.','collapse','fits','sound',NULL);
